3	import { useState, useEffect, useRef, useCallback } from "react";
4	import Image from "next/image";
5	import Link from "next/link";
6	import styles from "./beta-cta.module.css";
7	
8	const LEFT_BENEFITS = [
9	  "Beta pricing locked in",
10	  "Priority onboarding — live in 12 hours",
11	  "14-day satisfaction guarantee",
12	  "Pause or cancel anytime",
13	];
14	
15	const RIGHT_BULLETS = [
16	  "Founding pricing locked in before public rollout",
17	  "⚡ Priority onboarding — your team live in 12 hours",
18	  "🎁 Earn up to 20 free hours for beta feedback",
19	];
20	
21	function BetaModal({ onClose }: { onClose: () => void }) {
22	  const containerRef = useRef<HTMLDivElement>(null);
23	  const headingId = "beta-modal-heading";
24	
25	  // Escape key + focus trap
26	  const handleKeyDown = useCallback(
27	    (e: KeyboardEvent) => {
28	      if (e.key === "Escape") {
29	        onClose();
30	        return;
31	      }
32	      if (e.key !== "Tab" || !containerRef.current) return;
33	      const focusable = Array.from(
34	        containerRef.current.querySelectorAll<HTMLElement>(
35	          'a[href], button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])'
36	        )
37	      );
38	      if (!focusable.length) return;
39	      const first = focusable[0];
40	      const last = focusable[focusable.length - 1];
41	      if (e.shiftKey) {
42	        if (document.activeElement === first) {
43	          e.preventDefault();
44	          last.focus();
45	        }
46	      } else {
47	        if (document.activeElement === last) {
48	          e.preventDefault();
49	          first.focus();
50	        }
51	      }
52	    },
53	    [onClose]
54	  );
55	
56	  useEffect(() => {
57	    document.addEventListener("keydown", handleKeyDown);
58	    document.body.style.overflow = "hidden";
59	    // Auto-focus first focusable element
60	    const el = containerRef.current?.querySelector<HTMLElement>(
61	      'a[href], button:not([disabled])'
62	    );
63	    el?.focus();
64	    return () => {
65	      document.removeEventListener("keydown", handleKeyDown);
66	      document.body.style.overflow = "";
67	    };
68	  }, [handleKeyDown]);
69	
70	  return (
71	    <div
72	      className={styles["betaPopupOverlay"]}
73	      onClick={(e) => {
74	        if (e.target === e.currentTarget) onClose();
75	      }}
76	      role="dialog"
77	      aria-modal="true"
78	      aria-labelledby={headingId}
79	    >
80	      <div ref={containerRef} className={styles["betaPopupModal"]}>
81	        {/* Left panel */}
82	        <div className={styles["popupLeftPanel"]}>
83	          <div className={styles["popupBadge"]}>
84	            <div className={styles["popBadgeTxt"]}>
85	              <span aria-hidden="true">🔒</span> Exclusive Access
86	            </div>
87	          </div>
88	          <h2 id={headingId} className={styles["whiteHeading"]}>
89	            Private Beta Pricing
90	          </h2>
91	          <div className={styles["popupDivider"]} />
92	          <div className={styles["whatsIncluded"]}>
93	            WHAT&apos;S INCLUDED
94	          </div>
95	          <div className={styles["customPlanDlexdivNoWrap"]}>
96	            {LEFT_BENEFITS.map((benefit) => (
97	              <div key={benefit} className={styles["whiteLiIcon"]}>
98	                <div className={styles["liCheckSky"]}>
99	                  <Image
100	                    src="/images/webflow/Group-1.svg"
101	                    alt=""
102	                    aria-hidden="true"
103	                    width={19}
104	                    height={19}
105	                    className={styles["circleTick"]}
106	                  />
107	                </div>
108	                <p className={styles["paragraphSmallWhiteSmallFont"]}>
109	                  {benefit}
110	                </p>
111	              </div>
112	            ))}
113	          </div>
114	        </div>
115	
116	        {/* Right panel */}
117	        <div className={styles["popupRightPanel"]}>
118	          <div className={styles["eyebrowText"]}>
119	            Founding Partner Pricing
120	          </div>
121	          <h3 className={styles["popMainHd"]}>
122	            <strong>Start Your First Month with Beta Access</strong>
123	          </h3>
124	          <p
125	            className={`${styles["paragraph"]} ${styles["paragraphSmallFont"]}`}
126	          >
127	            Join Boldteq&apos;s private beta and experience our agency
128	            delivery infrastructure at founding pricing — before public
129	            launch moves to standard rates.
130	          </p>
131	          <div className={styles["popupUrgencyCard"]}>
132	            <div className={styles["redDot"]} aria-hidden="true" />
133	            <div className={styles["redRightTxt"]}>
134	              Only{" "}
135	              <strong className={styles["skyBold"]}>15 agencies</strong>{" "}
